    const trimStartX = Math.round(r.trim_start_norm * w);
    const trimEndX = Math.round(r.trim_end_norm * w);
    const loopStartX = Math.round(r.loop_start_norm * w);
    const loopEndX = Math.round(r.loop_end_norm * w);
