          const a = document.createElement("a");
          const safeName = (state.sampleName || "tepui_patch").toLowerCase().replace(/[^a-z0-9_-]+/g, "_");
          a.href = url;
          a.download = `${safeName}.tepui`;
          document.body.appendChild(a);
